-- ===========================================================================
--  The Pie Technologies — LEGACY upgrade script (pre-2026 databases only)
-- ===========================================================================
--  PREFERRED UPGRADE PATH: from Hostinger SSH run
--      php bin/cli.php migrate
--  It applies the additive migrations in database/migrations/ with per-column
--  checks and records versions in schema_migrations.
--
--  Only use THIS file for databases that predate the migration system, and
--  only AFTER a full database backup. Some ALTER TABLE statements fail if
--  re-run (MySQL/MariaDB "duplicate column"); treat an error as "already
--  applied" and continue. Fabricated demo content is DEACTIVATED, never
--  deleted — re-enable anything from the admin dashboard if you want it back.
-- ===========================================================================

SET FOREIGN_KEY_CHECKS = 0;

-- ------------------------- 1. Schema changes -------------------------------
ALTER TABLE portfolio ADD COLUMN industry VARCHAR(100) DEFAULT '' AFTER service_category;
ALTER TABLE resources ADD COLUMN slug VARCHAR(200) UNIQUE AFTER title;
ALTER TABLE resources ADD COLUMN content LONGTEXT AFTER description;
ALTER TABLE resources ADD COLUMN reading_time INT DEFAULT 5 AFTER category;
ALTER TABLE resources MODIFY COLUMN resource_type ENUM('guide','template','video','blueprint','playbook','checklist','framework','tutorial','case-study') DEFAULT 'guide';

CREATE TABLE IF NOT EXISTS payments (
  id INT AUTO_INCREMENT PRIMARY KEY,
  token VARCHAR(64) UNIQUE NOT NULL,
  name VARCHAR(150),
  email VARCHAR(150),
  reference VARCHAR(150),
  amount_usd DECIMAL(10,2) DEFAULT 0,
  notes TEXT,
  method ENUM('invoice','stripe','paypal') DEFAULT 'invoice',
  status ENUM('requested','pending','paid','failed','cancelled') DEFAULT 'requested',
  provider_ref VARCHAR(255) DEFAULT '',
  ip_address VARCHAR(45) DEFAULT '',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

