-- ---------------- 3. Real case studies (live-site Work page) ---------------
INSERT IGNORE INTO portfolio (client_name, service_category, industry, slug, thumbnail, challenge, strategy, results, stats_json, chart_data_json, testimonial, testimonial_author, display_order, is_active) VALUES
('Confidential — Professional Services', 'Meta Ads, Website Development, Data Analytics', 'Professional Services', 'lead-generation-engine-meta-ads', 'assets/images/work-saas.jpg', 'The firm was boosting posts and sending all traffic to a generic homepage. Leads were sporadic, unqualified, and nobody could say which ad produced which enquiry.', 'Replace "boosting" with an engineered funnel: one offer per campaign, dedicated landing pages matched to each audience, Meta Pixel + Conversions API tracking, and a creative testing matrix so winning angles scale on evidence.', 'Execution, end to end: a full tracking rebuild (Pixel, Conversions API, UTM discipline); campaign architecture split by audience temperature; weekly creative testing across hooks, formats and offers; purpose-built landing pages per campaign; and a lead-quality feedback loop with the client''s intake team — so what "qualified" means is agreed with the people answering the phone, not assumed in the ads manager. Outcomes are reported against cost per qualified lead; specific figures are client-confidential.', NULL, NULL, NULL, NULL, 1, 1),
('Confidential — Home Services', 'Local SEO, SEO, Data Analytics', 'Home Services', 'local-visibility-system-home-services', 'assets/images/why-team.jpg', 'A multi-crew home services business relied almost entirely on word of mouth. Their Google Business Profile was unmanaged, service areas were undefined, and competitors with weaker reputations outranked them on the map.', 'Treat local visibility as infrastructure, not a campaign: a complete Google Business Profile rebuild, service-area architecture, a steady review-generation flow and consistent citations — tied together with call and form tracking so outcomes are attributable.', 'Execution, end to end: the Google Business Profile rebuilt and categorized with services, photos and Q&A; location and service-area pages created with local schema; a post-job review request flow installed (SMS + email); citations cleaned and standardized across major directories; and calls and form leads tracked from day one — so every ring is attributable to the visibility work that produced it. Specific figures are client-confidential.', NULL, NULL, NULL, NULL, 2, 1);

