-- ------------------------------ 7. Journal posts ---------------------------
INSERT INTO blog_posts (title, slug, category_id, featured_image, excerpt, content, tags, author, meta_title, meta_description, reading_time, views, status, published_at)
SELECT 'Why "Post More" Is the Worst Social Media Advice in Marketing', 'why-post-more-is-bad-advice', (SELECT id FROM blog_categories WHERE slug = 'social-media' LIMIT 1), 'assets/images/blog-social.jpg', 'Volume without identity is noise. Here is the framework we use instead — pillars, formats, rhythm and the feedback loop that actually grows an account.', '<p>Every struggling account we audit was told the same thing by someone: post more. And every struggling account obeyed — five posts a week of whatever was handy, each one a little different from the last, none of them adding up to anything. Then the numbers stayed flat and the conclusion was “social doesn’t work for us.”</p><p>It does. The advice was just backwards. Volume without identity is noise; identity without rhythm is a hobby. Growth comes from the structure underneath the posting.</p><h2>Pillars before posts</h2><p>Before anything gets designed, every account we run gets four pillars, each with a job: <strong>Educate</strong> — answer the questions your sales team repeats every week. <strong>Prove</strong> — results, completed jobs, before-and-afters, customer words. <strong>Humanize</strong> — the team, the process, the opinions. <strong>Convert</strong> — offers with one clear next step. Every post is assigned a pillar and a job before it exists. If it has neither, it doesn’t get made.</p><h2>Formats are platform-native or invisible</h2><p>One idea, adapted per platform: Reels for reach, carousels for saves, stories for conversation, documents for LinkedIn authority. Cross-posting the same asset unchanged everywhere is how brands manage to be present on five platforms and memorable on none.</p><h2>Rhythm beats volume</h2><p>A sustainable cadence — three strong posts and daily engagement — outperforms seven rushed posts and an empty comment section. The weekly rhythm matters more than the weekly count: publish from an approved calendar, spend a real hour in the comments and DMs, and capture raw material (job photos, customer wins, team moments) into a content bank every Friday so next month’s batch is never a scramble.</p><h2>The feedback loop</h2><p>This is the part “post more” never includes. Judge posts on business outcomes — profile visits, link clicks, DM conversations, leads — not follower theater. Each month, the top two performers get doubled down into next month’s calendar and the weakest pillar mix gets rewritten. The account learns; that’s what growth actually looks like.</p><blockquote>Frequency is a tactic. Identity, rhythm and feedback are the system. The system is what compounds.</blockquote><p>If your posting has been climbing while your results stay flat, the answer is not the eighth post this week. It’s the framework underneath all of them — and the honest monthly review that keeps tightening it.</p>', 'social media, content strategy, growth', 'TPT Strategy Team', 'Why "Post More" Is the Worst Social Media Advice in Marketing | TPT Journal', 'Volume without identity is noise. Here is the framework we use instead — pillars, formats, rhythm and the feedback loop that actually grows an account.', 2, 0, 'published', NOW() - INTERVAL 3 DAY FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM blog_posts WHERE slug = 'why-post-more-is-bad-advice');

INSERT INTO blog_posts (title, slug, category_id, featured_image, excerpt, content, tags, author, meta_title, meta_description, reading_time, views, status, published_at)
SELECT 'Is Your Website a Brochure or a Salesperson? A 10-Point Check', 'website-brochure-or-salesperson', (SELECT id FROM blog_categories WHERE slug = 'websites' LIMIT 1), 'assets/images/work-saas.jpg', 'Most business websites describe; few persuade. A ten-minute honesty check to find out which one you own — and the three fixes that pay back fastest.', '<p>Your best salesperson would never greet a prospect by talking about themselves. Yet that is exactly what most business websites do: history, mission, team photos, a wall of services — and a “Contact Us” button that asks for faith instead of giving a reason. Brochures describe. Salespeople persuade. Here is the ten-point check.</p><h2>The check</h2><ul><li><strong>1. Five-second test.</strong> Can a stranger say what you do, for whom, and why you — from the top of the homepage alone?</li><li><strong>2. One primary action.</strong> Does every page have exactly one next step, or six competing ones?</li><li><strong>3. Proof placement.</strong> Do testimonials and results appear near the ask — or are they buried on an About page nobody reaches?</li><li><strong>4. Objection answers.</strong> Does the site answer the questions your sales team hears every day — cost, timeline, trust, process?</li><li><strong>5. Speed on a real phone.</strong> Not your office desktop: a mid-range phone on mobile data. Under 2.5 seconds or it’s taxed.</li><li><strong>6. Form friction.</strong> Does your form qualify (budget, timing, area) or just collect names into a void?</li><li><strong>7. Lead routing.</strong> When a form is submitted, does a human know within five minutes?</li><li><strong>8. Mobile-first paths.</strong> Is the phone number tappable everywhere, and does the menu reach money pages in two taps?</li><li><strong>9. Measurement.</strong> Can you say which page produced last month’s leads — or only how many visitors you had?</li><li><strong>10. Freshness.</strong> Does anything on the site prove the business is alive this quarter?</li></ul><h2>The three fixes that pay back fastest</h2><p>If you scored badly, don’t rebuild everything. Start with these: <strong>Rewrite the homepage hero</strong> to state the outcome you deliver in the customer’s words (a day of work, lifts every campaign pointing at it). <strong>Move proof next to the ask</strong> — testimonials beside forms, results beside claims (an afternoon, changes the temperature of every visit). <strong>Wire routing and tracking</strong> so submissions reach a human in minutes and you can finally see which pages produce pipeline (a weekend, ends the guessing forever).</p><blockquote>A brochure costs money to maintain. A salesperson earns it back. The difference is never the design — it’s the job the page was built to do.</blockquote><p>Run the ten points honestly. Most sites fail four or five — and the fixes are usually weeks, not months.</p>', 'websites, conversion, web development', 'TPT Strategy Team', 'Is Your Website a Brochure or a Salesperson? A 10-Point Check | TPT Journal', 'Most business websites describe; few persuade. A ten-minute honesty check to find out which one you own — and the three fixes that pay back fastest.', 2, 0, 'published', NOW() - INTERVAL 7 DAY FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM blog_posts WHERE slug = 'website-brochure-or-salesperson');

INSERT INTO blog_posts (title, slug, category_id, featured_image, excerpt, content, tags, author, meta_title, meta_description, reading_time, views, status, published_at)
SELECT 'Local SEO in 2026: What Actually Moves the Map Pack', 'local-seo-what-moves-map-pack', (SELECT id FROM blog_categories WHERE slug = 'local-seo' LIMIT 1), 'assets/images/why-data.jpg', 'Forget the folklore. After auditing dozens of local profiles, here is what genuinely moves rankings: category discipline, review velocity, and pages that prove you serve where you say.', '<p>Local SEO folklore is a whole industry: citation blast services, geo-tagged photo tricks, “secret” ranking buttons in the Business Profile. After auditing dozens of local profiles — and watching which changes actually moved grid rankings — the honest list is shorter and more boring. That’s good news: boring is repeatable.</p><h2>1. Category discipline</h2><p>Your primary category tells Google what search moments you belong in; the secondary categories refine it. Most profiles we audit have a primary category chosen at setup and never revisited — “Contractor” when “Roofing Contractor” is the money category, or a secondary list padded with services the profile can’t evidence. Map every category to real search demand, keep secondaries honest, and align the services list and description with what you actually sell.</p><h2>2. Review velocity — recent beats total</h2><p>A competitor with 140 stale reviews loses to you with 40 arriving steadily, answered within 24 hours and specific about the job. Install a post-job request flow (SMS + email, timed when the win is fresh), answer everything in your voice, and track velocity monthly. Reviews are also content: the words customers use become the words your pages should use.</p><h2>3. Pages that prove service areas</h2><p>“We serve the tri-state area” is a claim; a page per service × area with real jobs, local schema, directions and photos is evidence. Google (and every AI assistant reading your site) rewards evidence. Build the architecture honestly — no PO-box cities, no doorway pages with swapped nouns. Those get listings suspended.</p><h2>4. Profile freshness</h2><p>Photos, posts and Q&amp;A signal a business that exists this month, not this decade. A ten-minute weekly touch — new job photos, one post, answered questions — outperforms a quarterly content blitz.</p><h2>What didn’t make the list</h2><p>Citation-blast services (consistency matters; volume beyond the major directories doesn’t), geo-tagging photos, embedding keywords in the business name (against the rules and enforced), and any tool promising to “hack the map pack.” None survived contact with real grid data.</p><blockquote>The map pack is won by completeness, recency and evidence — maintained weekly. There is no trick, which is exactly why it works.</blockquote><p>Run a grid scan of your service areas, fix the categories this week, install the review flow this month, and build the area pages next quarter. In six months the map looks different.</p>', 'local seo, google business profile, map pack', 'TPT Strategy Team', 'Local SEO in 2026: What Actually Moves the Map Pack | TPT Journal', 'Forget the folklore. After auditing dozens of local profiles, here is what genuinely moves rankings: category discipline, review velocity, and pages that prove you serve where you say.', 2, 0, 'published', NOW() - INTERVAL 12 DAY FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM blog_posts WHERE slug = 'local-seo-what-moves-map-pack');

